"""Observation regions: NASA POWER cells that hold peat, generated by tools/build_regions.py."""
from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path


@dataclass(frozen=True)
class Region:
    id: str
    lat: float          # POWER cell centre; a point request here returns this cell
    lon: float
    bounds: tuple[float, float, float, float]   # west, south, east, north
    province: str       # BPS code of the province holding most of the region's peat
    peat_km2: float


@lru_cache
def load_regions(path: str | None = None) -> tuple[Region, ...]:
    data = json.loads(Path(path or Path(__file__).with_name("regions.json")).read_text(encoding="utf-8"))
    return tuple(Region(r["id"], r["lat"], r["lon"], tuple(r["bounds"]), r["province"], r["peat_km2"])
                 for r in data["regions"])
